// Deterministic frame capture: drive scene.html frame-by-frame in headless Chrome.
const puppeteer = require('puppeteer-core');
const path = require('path');
const fs = require('fs');

const FPS = 60;
const OUT = path.join(__dirname, 'frames');
const ONLY = process.argv.slice(2).filter(a => !a.startsWith('--'));

(async () => {
  fs.rmSync(OUT, { recursive: true, force: true });
  fs.mkdirSync(OUT, { recursive: true });

  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--force-device-scale-factor=1',
           '--hide-scrollbars', '--disable-lcd-text']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1920, height: 1080, deviceScaleFactor: 1 });
  await page.goto('file://' + path.join(__dirname, 'scene.html'), { waitUntil: 'load' });

  const dur = await page.evaluate(() => window.DURATION);

  if (ONLY.length) {                         // preview mode: specific timestamps
    for (const ts of ONLY) {
      const t = parseFloat(ts);
      await page.evaluate(t => window.draw(t), t);
      await page.screenshot({ path: path.join(OUT, `p_${ts}.png`) });
    }
    await browser.close();
    console.log('preview frames written');
    return;
  }

  const total = Math.round(dur * FPS);
  for (let i = 0; i < total; i++) {
    await page.evaluate(t => window.draw(t), i / FPS);
    await page.screenshot({
      path: path.join(OUT, String(i).padStart(5, '0') + '.png'),
      optimizeForSpeed: true
    });
    if (i % 120 === 0) console.log(`${i}/${total}`);
  }
  await browser.close();
  console.log(`done ${total} frames`);
})();

